"""Builds NOTE.html: the short public-facing note, led by the validated claim. Reuses the lab book's figure builders and numbers (imports labbook/make_labbook.py, which rebuilds LABBOOK.html first).
Run: python3 -I labbook/make_note.py"""
import os, sys
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, os.path.join(HERE, "labbook"))
import make_labbook as L
esc, f2, f3, pct = L.esc, L.f2, L.f3, L.pct; NOIMG = L.NO_IMAGES
m4, m3c, devA, devB, PAIRS = L.m4, L.m3c, L.devA, L.devB, L.PAIRS
T2a, T2t = m4["T2"]["all"], m4["T2"]["test"]; C4 = m4["classes"]; sp = L.sc_pairs; bl = m3c["baselines"]
L.FIGN[0] = 0
fig_how = L.figure("How a position reading is computed on a photograph.", ("A synthetic image" if NOIMG else "A real photograph (PICD, credit at the end)") + " beside its row profile: the mean vertical gradient of each row. The strongest horizontal line sets y*. Shaded bands are the tolerance around 1/3, 1/2 and 2/3.", L.fig_how(), L.HOWTXT.replace(" (see the thirds-to-phi sweep below)", ""))
fig_ovl = L.figure("What the readings report on four photographs.", "One image drawn at random (seeded) from each of four PICD categories. White dashed lines mark 1/3, 1/2 and 2/3; the solid line is the measured position. Images from PICD (Zhao et al., CVPR 2025), the part released for redistribution, shown reduced and uncropped under CC BY-NC-SA 4.0 and the dataset's Terms of Use; the dataset does not record photographer or platform per image; ids shown.", L.fig_overlays(plan=((8, "h"), (9, "h"), (12, "v"), (13, "v"))), "The measured line is not always where the category name suggests; the reading is a measurement of the picture, not a copy of its label.")
fig_agree = L.figure("Does the reading agree with where people drew the line?", "CADB, all 9,497 photographs: images with exactly one annotated horizontal (n = " + str(T2a["horizontal"]["n"]) + ") or vertical (n = " + str(T2a["vertical"]["n"]) + ") segment. Each dot is one photograph; the dashed line is perfect agreement. The reading was fixed and hashed before CADB was read once.", L.fig_cadb_agree(), f"Horizontal: median error {T2a['horizontal']['median_error']:.3f} of the image height against {T2a['horizontal']['null_median_error']:.3f} when the marks are shuffled across images; vertical {T2a['vertical']['median_error']:.3f} against {T2a['vertical']['null_median_error']:.3f}.")
fig_hist = L.figure("Where the strongest line sits, by category (PICD, fresh images).", "40 images per category, LockboxB, read once.", L.fig_hist(sel=(0, 1)), "Middle categories cluster at 1/2; third categories sit at 1/3 and 2/3.")
fig_pairs = L.figure("The two line pairs on three sets of PICD images.", "AUC of the line-position reading: the chance that a random image of the thirds category scores higher than one of the middle category (0.5 is no separation). The pooled DINOv3 probe is a trained model plus a fitted layer, trained on about 69 images per category.", L.fig_pairs(keys=PAIRS[:2]), "Both pairs separate on all three sets. A pooled whole-image embedding trained on about 69 images per category stays at 0.54 and 0.64 on the confirmation half; trained on 138 per category and tested on fresh images it reaches 0.74 and 0.64 (see the text).")
fig_curves = L.figure("Trained probes with position-aware features catch up given labelled images.", "Lines: mean of 10 random splits on the PICD pool; diamonds: trained on the whole pool, tested on fresh images. The dashed line is the reading, which uses no labelled image.", L.fig_curves(keys=PAIRS[:2]), "The reading's advantage is that it needs no labelled images, not a higher ceiling.")
fig_cadb = L.figure("The reading and the other scores on CADB's composition classes.", "CADB test split (950 images); multi-label images count as positives for each of their classes. Bold labels are classes whose lens score does not clear 0.5 with its interval (diagonal was a pre-stated prediction; golden ratio, triangle and curved had none; vanishing point was predicted not to).", L.fig_cadb_classes(), "The line coverage scores carry the result; thirds and centre are barely above chance; a fitted probe on DINOv3 is ahead on every class.")
LINKS = os.environ.get('LENS_LINKS') == '1'
LINK_LAB = '<a href="labbook.html">the lab book</a>' if LINKS else '<code>composition-lens/LABBOOK.html</code>'
LINK_REPO = '<a href="https://github.com/parallaxmetrology/composition-lens">github.com/parallaxmetrology/composition-lens</a>' if LINKS else '<code>composition-lens/</code>'
BYLINE = ('Russell Parrish, Parallax Metrology. Note, 20 November 2026. Not peer reviewed. &middot; <a href="https://github.com/parallaxmetrology/composition-lens">Code and data</a> &middot; <a href="labbook.html">Lab book</a>' if LINKS else 'Russell Parrish, 20 Nov 2026. Local draft. Every number comes from results files listed at the end; the full record is the lab book (LABBOOK.html).')
CSS = L.CSS + "\nmain{max-width:800px}.lede{font-size:1.08rem}"
body = f"""<h1>Where the line sits: reading horizon and vertical-line position in photographs, checked against human marks</h1>
<p class="sub">{BYLINE}</p>
<p class="lede">Photographers describe composition by where things sit: a horizon in the middle or on a third of the frame, a vertical line at the centre or on a third, a subject on a power point. We built plain, named measurements of the strongest horizontal and vertical lines in a photograph, with no model trained on photographs, and checked them against people in two ways. They agree with where annotators drew lines, and they separate expert-labelled categories that whole-image methods could not. The same approach did not work for subject placement, and this note says so.</p>
<div class="key"><b>The claim.</b> On CADB (9,497 photographs, read once), where annotators marked one horizontal line, the horizon reading lies within 0.05 of the image height of it for {pct(T2a['horizontal']['within_0_05'])} of images (median error {T2a['horizontal']['median_error']:.3f}, against {T2a['horizontal']['null_median_error']:.3f} when the marks are shuffled); the vertical reading agrees similarly ({pct(T2a['vertical']['within_0_05'])} within 0.05; median {T2a['vertical']['median_error']:.3f} against {T2a['vertical']['null_median_error']:.3f}). On PICD the same readings separate horizon-in-the-middle from horizon-on-a-third (AUC {f2(sp[PAIRS[0]][2])} on fresh images) and the vertical-line pair ({f2(sp[PAIRS[1]][2])}), where whole-image methods stayed near chance. <b>Not established:</b> subject placement. The compact-object reading did not follow the annotators' subject boxes on CADB, so a third PICD pair (a subject at the centre vs at a power point) is not claimed; the thirds-point and centre-point scores are barely above chance on CADB, and the diagonal, golden and perspective scores are not supported on real photographs.</div>
<h2>1. Background</h2>
<p><b>The datasets.</b> <b>PICD</b> (Zhao et al., CVPR 2025) labels each of its photographs with one of 24 composition categories, for example "Horizontal Middle Part" and "Horizontal Third Part". <b>CADB</b> (Zhang, Niu and Zhang, BMVC 2021) labels each photograph with one or more of 13 classes and includes the annotators' own drawn marks (lines, boxes). <b>The problem.</b> In an earlier benchmark study five PICD category pairs stayed near coin-flip accuracy for every method we tried, including three well-known learned models, and the data could not say whether the categories overlap or the methods are too coarse. Those methods each reduce a picture to one summary vector with no record of where things sit; we call them whole-image methods. <b>A reading</b> is a named number computed from an image with no training, such as "the strongest horizontal line sits at 0.37 of the height". Each reading has a written definition and can be inspected on the picture.</p>
<p><b>How to read the numbers.</b> <b>AUC</b> (one-vs-rest or pairwise) is the chance that a random image of the target category scores higher than a random image of the other category or categories: 0.5 means no separation and 1 means perfect. Intervals are 95% bootstrap intervals. A <b>fitted layer</b> is a logistic regression trained on labelled images and is called one wherever it appears; the readings themselves are training-free (two detection thresholds were calibrated on synthetic images). <b>Discipline:</b> a written plan fixed the definitions and the predictions before each real-photograph test; the PICD readings were designed on one half of a held-out pool, confirmed once on the other half, and tested once on 960 fresh images; CADB was read once.</p>
<h2>2. What is measured</h2>
{fig_how}{'' if NOIMG else fig_ovl}
<h2>3. Result: it agrees with where people drew the line</h2>
<p>CADB annotators drew the elements they saw for each composition class, in each photograph's own pixel frame. For photographs with exactly one marked horizontal segment, we compared its height with the reading's y*. The comparison is a direct check against human marks, not against a category label. Shuffling the marks across photographs gives the null: errors four to six times larger.</p>
{fig_agree}
<p>On the official test split alone the numbers are the same in kind (horizontal n = {T2t['horizontal']['n']}, median error {T2t['horizontal']['median_error']:.3f}; vertical n = {T2t['vertical']['n']}, median {T2t['vertical']['median_error']:.3f}). About half of the photographs fall within 0.05 of the image height; the rest scatter. We have not analysed why; a likely cause is photographs with no single dominant line.</p>
<h2>4. Result: it separates categories that whole-image methods could not</h2>
<p>In the earlier benchmark, "horizontal middle" vs "horizontal third" and "vertical middle line" vs "vertical third line" scored 0.49 to 0.55 pair accuracy for every method. The category definitions are about position, and the line readings report position.</p>
{fig_hist}{fig_pairs}
<p>A fair question is whether the reading beats learned models or only beats a pooled embedding that is built to discard position. We gave learned probes position-aware features (a map of where DINOv3's features are strong, or a plain 16 x 16 grid of edge strength) and up to 138 labelled images per category. They match or pass the reading from about 20 to 40 labelled images for the vertical pair, and are level with it for the horizon pair on fresh images (edge grid {f2(bl[PAIRS[0]]['G-edge']['auc'])} against the reading's {f2(sp[PAIRS[0]][2])}; vertical {f2(bl[PAIRS[1]]['G-edge']['auc'])} against {f2(sp[PAIRS[1]][2])}), while the pooled embedding stays at {f2(bl[PAIRS[0]]['D-pool']['auc'])} and {f2(bl[PAIRS[1]]['D-pool']['auc'])}. So the categories do differ in position as defined, and the reading's advantage is that it needs no labelled image, not a higher ceiling.</p>
{fig_curves}
<h2>5. Where else it works on CADB, and where it does not</h2>
<p>Zero-shot, the line coverage scores (how much of the frame's width or height the strongest line's edge spans) rank CADB's horizontal and vertical classes above the rest (AUC {f2(C4['horizontal']['lens_auc_test'])} and {f2(C4['vertical']['lens_auc_test'])}). The thirds and centre scores, which depend on where a subject sits, are barely above chance ({f2(C4['rule_of_thirds']['lens_auc_test'])} and {f2(C4['center']['lens_auc_test'])}); diagonal ({f2(C4['diagonal']['lens_auc_test'])}), golden ratio ({f2(C4['golden_ratio']['lens_auc_test'])}), triangle ({f2(C4['triangle']['lens_auc_test'])}), spiral ({f2(C4['curved']['lens_auc_test'])}) and perspective ({f2(C4['vanishing_point']['lens_auc_test'])}, interval crossing 0.5) are not supported. A fitted DINOv3 probe is ahead of every zero-shot score on every class, so as a classifier the readings are weaker; their value is that they are named and checkable.</p>
{fig_cadb}
<h2>6. What is open, and what this does not show</h2>
<ul><li><b>Subject placement is not solved.</b> The compact-object reading separated a "subject at the centre" from a "subject at a power point" category on PICD (AUC {f2(sp['P-RoT vs P-Cent'][2])} on fresh images), but on CADB its location does not follow the annotated subject boxes (median distance {T2t['center_box']['median_error']:.2f} against {T2t['center_box']['null_median_error']:.2f} for shuffled boxes), and a patch-norm probe separates the same PICD pair far better ({f2(bl['P-RoT vs P-Cent']['D-norm']['auc'])}). We hold that pair back. A better subject reading would probably need a trained saliency model, labelled as such, and CADB's boxes give it a ground truth.</li>
<li>Other named templates (golden triangle, golden spiral, phi and fifths grids, rabatment, vanishing-point counts) were built and tested on exact synthetic layouts only, where they pass, but have no real-photograph support here.</li>
<li>Two of the five hard PICD pairs (arrangements of several points) have no reading yet. We have no annotator-agreement data, so the partial separation (AUC {f2(min(sp[k][2] for k in PAIRS[:2]))} to {f2(max(sp[k][2] for k in PAIRS[:2]))} on fresh images) is not interpreted as label noise or as overlap.</li>
<li>The evidence is two web-photograph datasets at a 384-pixel working size, with 40 images per category on the fresh set (intervals of about +/- 0.1). The line readings assume a dominant line; scenes without one are read less well.</li></ul>
<h2>Method and records</h2>
<p class="small">Readings: lens/ (profiles of mean gradient across rows and columns; tolerance 1.5% of the frame; PLAN.md fixes every definition). Specifications hashed before the confirmation, fresh and CADB runs: <code>{L.spec['m3'][0][:8]}…</code> (PICD confirmation), <code>{L.spec['m3c'][0][:8]}…</code> (PICD fresh), <code>{L.spec['m4'][0][:8]}…</code> (CADB); each real-photograph run was read once and the guards refuse a second run (the first CADB extraction hung without producing any output; the script was made crash-safe and the specification re-frozen before the rerun, a change logged as amendment A6). Comparators: a fitted logistic probe on DINOv3 (timm weights, offline), probes on patch-token maps and on brightness and edge-strength grids, and a reimplementation of Facet's thirds and centre heuristic. Full lab book with synthetic tests, claims ledger, amendments, fallen ideas and reproduction commands: {LINK_LAB}. Code, derived results and a script that recomputes the real-photograph numbers: {LINK_REPO}. The five-pair question comes from an earlier benchmark study of PICD (not published).</p>
<h2>Image credit</h2>
<p class="small">{'This edition shows no dataset images. ' if NOIMG else ''}{'Example images (in the edition on parallaxmetrology.com) are from PICD' if NOIMG else 'Example images are from PICD'} (Zhao et al., CVPR 2025), the part of the dataset released for redistribution, shown at reduced size and uncropped. The dataset is released under CC BY-NC-SA 4.0 and its Terms of Use (non-commercial academic and educational use); it comes from open platforms (Unsplash, Pexels, Flickr) and redistributable datasets and does not record the photographer or platform per image, so credit is to the dataset and the image ids are given. CADB (built on AADB Flickr images, research use only) was used locally and none of its images are shown. Please see the <a href="https://github.com/CV-xueba/PICD_ImageComposition">PICD page</a> for the terms before reusing any image.</p>"""
doc = f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Where the line sits: reading horizon and vertical-line position in photographs</title><style>{CSS}</style></head><body><main>{body}</main></body></html>'
if LINKS: doc = doc.replace("<title>", '<link rel="canonical" href="https://parallaxmetrology.com/composition-lens/"><meta name="description" content="Plain, named readings of the strongest horizontal and vertical lines in a photograph agree with where annotators drew lines (CADB, 9,497 photographs) and separate PICD categories that whole-image methods could not. Subject placement is open."><title>', 1)
open(os.path.join(L.OUTDIR, "NOTE.html"), "w").write(doc)
SVGDIR = os.environ.get("LENS_SVG_DIR")
if SVGDIR:
    import re
    os.makedirs(SVGDIR, exist_ok=True); css = L.CSS.split("*{box-sizing")[0] + "svg text{font-family:system-ui,-apple-system,'Segoe UI',sans-serif}" + "".join(r for r in L.CSS.split("\n") if r.startswith((".t{", ".gl{", ".ln{", ".ls1", ".s1", ".fr2")))
    for name, fg in (("cadb-line-agreement", fig_agree), ("pair-auc-line-pairs", fig_pairs), ("learning-curves", fig_curves), ("cadb-class-auc", fig_cadb), ("picd-line-positions", fig_hist)):
        m = re.search(r"<svg viewBox=\"0 0 ([\d.]+) ([\d.]+)\".*?</svg>", fg, re.S); sv = m.group(0); w, h = float(m.group(1)), float(m.group(2))
        sv = sv.replace('width="100%"', f'width="{w:.0f}" height="{h:.0f}"', 1).replace(">", "><style>" + L.CSS.replace("</", "<\\/") + "</style>", 1)
        open(os.path.join(SVGDIR, name + ".svg"), "w").write(sv)
    print("wrote", len(os.listdir(SVGDIR)), "svg figures"); print("wrote NOTE.html", len(doc) // 1024, "KB;", L.FIGN[0], "figures")
